-- ============================================================================
-- RLS rebuild: tenant isolation + role hierarchy
-- ============================================================================
-- Why: the policies generated by the Base44 import compare company_id to the
-- literal string '{{user.data.company_id}}' (never substituted), so tenant
-- scoping never worked: admin/manager saw every company, everyone else saw
-- nothing. Several tables were also open to anon (`true` policies or RLS off),
-- and core.users was writable by any signed-in user.
--
-- Role model after this migration:
--   super_admin  eFin staff. Every company, every table.
--   admin        Dealership owner. Everything inside their own company.
--   manager      Day-to-day operations inside their own company.
--   accountant / sales / technician / inventory_manager / user
--                Company members; module access is enforced in the app.
--
-- Every existing policy on the tables below is DROPPED and recreated, so this
-- file is the single source of truth for their access rules.
-- Service-role clients (edge functions, webhooks) bypass RLS and are unaffected.
-- ============================================================================

begin;

-- ----------------------------------------------------------------------------
-- 1. Data cleanup + role constraint
-- ----------------------------------------------------------------------------

update core.users set company_id = null where company_id::text = '';
update core.users set role = 'user' where role is null or role = '';

do $$
declare r record;
begin
  for r in
    select conname from pg_constraint
    where conrelid = 'core.users'::regclass and contype = 'c'
      and pg_get_constraintdef(oid) ilike '%role%'
  loop
    execute format('alter table core.users drop constraint %I', r.conname);
  end loop;
end $$;

alter table core.users
  add constraint users_role_check check (role in (
    'super_admin', 'admin', 'manager', 'accountant',
    'sales', 'technician', 'inventory_manager', 'user'
  ));
alter table core.users alter column role set default 'user';

-- eFin staff (confirmed 2026-10-31).
update core.users set role = 'super_admin'
where id in (
  'b7784ec8-5387-3df0-92ac-09f841a1185d',  -- sam@matibiniassociates.biz
  '582f5d59-faad-3665-a5a2-83eb5db02250',  -- sam@efintax.biz
  '6ab86aa3-864a-3cc6-959f-4934b498a42b',  -- smatibini.sm@gmail.com
  'ea2a36b6-c9bd-3774-a89c-bdc00ea2df88',  -- egwuonucheojosamuel@gmail.com
  'c1c123d7-dbca-32d7-b59f-c875f35c26f0'   -- kamsinnaegbuna@gmail.com
);

-- ----------------------------------------------------------------------------
-- 2. Helper functions
-- ----------------------------------------------------------------------------
-- SECURITY DEFINER so policies can read core.users without recursing into its
-- own RLS. Policies call them as `(select core.fn())` so Postgres evaluates
-- each once per statement instead of once per row.

grant usage on schema core to authenticated;

create or replace function core.current_user_role()
returns text language sql stable security definer set search_path = '' as $$
  select u.role from core.users u where u.id = auth.uid()
$$;

create or replace function core.current_company_id()
returns text language sql stable security definer set search_path = '' as $$
  select nullif(u.company_id::text, '') from core.users u where u.id = auth.uid()
$$;

create or replace function core.current_employee_id()
returns text language sql stable security definer set search_path = '' as $$
  select nullif(u.employee_entity_id::text, '') from core.users u where u.id = auth.uid()
$$;

create or replace function core.is_super_admin()
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select u.role = 'super_admin' from core.users u where u.id = auth.uid()), false)
$$;

create or replace function core.role_rank(r text)
returns integer language sql immutable set search_path = '' as $$
  select case r
    when 'super_admin' then 100
    when 'admin' then 80
    when 'manager' then 60
    when 'accountant' then 20
    when 'sales' then 20
    when 'technician' then 20
    when 'inventory_manager' then 20
    when 'user' then 10
    else 0
  end
$$;

-- Highest role rank the caller may assign or manage:
-- admins manage up to admin, managers only staff below manager.
create or replace function core.max_assignable_rank()
returns integer language sql stable security definer set search_path = '' as $$
  select case core.current_user_role()
    when 'super_admin' then 100
    when 'admin' then 80
    when 'manager' then 59
    else 0
  end
$$;

grant execute on function
  core.current_user_role(), core.current_company_id(), core.current_employee_id(),
  core.is_super_admin(), core.role_rank(text), core.max_assignable_rank()
to authenticated;

-- Fill company_id on insert when the client leaves it empty.
create or replace function core.default_company_id()
returns trigger language plpgsql set search_path = '' as $$
begin
  if new.company_id is null or new.company_id::text = '' then
    new.company_id := core.current_company_id();
  end if;
  return new;
end $$;

-- ----------------------------------------------------------------------------
-- 3. Policy builder (temporary, dropped with the session)
-- ----------------------------------------------------------------------------

create function pg_temp.reset_policies(
  tbl text, sel text, ins text, upd text, del text, add_company_default boolean
) returns void language plpgsql as $$
declare r record;
begin
  if to_regclass('public.' || tbl) is null then
    raise notice 'skipping missing table public.%', tbl;
    return;
  end if;

  for r in select policyname from pg_policies where schemaname = 'public' and tablename = tbl loop
    execute format('drop policy %I on public.%I', r.policyname, tbl);
  end loop;

  execute format('alter table public.%I enable row level security', tbl);

  if sel is not null then
    execute format('create policy %I on public.%I for select to authenticated using (%s)', tbl || '_select', tbl, sel);
  end if;
  if ins is not null then
    execute format('create policy %I on public.%I for insert to authenticated with check (%s)', tbl || '_insert', tbl, ins);
  end if;
  if upd is not null then
    execute format('create policy %I on public.%I for update to authenticated using (%s) with check (%s)', tbl || '_update', tbl, upd, upd);
  end if;
  if del is not null then
    execute format('create policy %I on public.%I for delete to authenticated using (%s)', tbl || '_delete', tbl, del);
  end if;

  if add_company_default then
    execute format('drop trigger if exists trg_default_company_id on public.%I', tbl);
    execute format(
      'create trigger trg_default_company_id before insert on public.%I for each row execute function core.default_company_id()',
      tbl);
  end if;
end $$;

-- Row belongs to the caller's company (or caller is super_admin).
create function pg_temp.tenant(col text default 'company_id') returns text language sql as $$
  select format('((select core.is_super_admin()) or %I::text = (select core.current_company_id()))', col)
$$;

-- Row belongs to the caller's company AND caller holds one of `roles`.
create function pg_temp.tenant_role(roles text, col text default 'company_id') returns text language sql as $$
  select format(
    '((select core.is_super_admin()) or (%I::text = (select core.current_company_id()) and (select core.current_user_role()) = any (%L::text[])))',
    col, roles)
$$;

-- ----------------------------------------------------------------------------
-- 4. Tenant tables: company members read/create/edit; admin & manager delete
-- ----------------------------------------------------------------------------

do $$
declare
  t text;
  managers constant text := '{admin,manager}';
begin
  foreach t in array array[
    'bills', 'cargos', 'communication_logs', 'containers', 'credit_notes',
    'crmtasks', 'custom_reports', 'customers', 'document_sequences',
    'document_templates', 'driver_performance_metrics', 'drivers',
    'exchange_rates', 'expenses', 'export_documents', 'export_orders',
    'exports', 'freight_shipments', 'geofences', 'hazmat_incidents',
    'invoices', 'leads', 'loading_declarations', 'local_shipments',
    'notification_logs', 'notification_preferences', 'opportunities',
    'parts', 'payment_links', 'payment_mades', 'payment_receiveds',
    'payment_transactions', 'products', 'project_tasks', 'projects',
    'purchases', 'quotes', 'recurring_bills', 'recurring_expenses',
    'recurring_invoices', 'repair_orders', 'sale_signatures', 'sales',
    'sales_invoices', 'salvage_vehicles', 'service_packages', 'services',
    'shipment_trackings', 'shipping_documents', 'signature_requests',
    'technicians', 'third_party_carriers', 'third_party_drivers',
    'time_entries', 'timesheets', 'trailers', 'truck_vehicles', 'vehicles',
    'vendor_credits', 'vendors'
  ] loop
    perform pg_temp.reset_policies(
      t,
      pg_temp.tenant(), pg_temp.tenant(), pg_temp.tenant(),
      pg_temp.tenant_role(managers),
      true);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 5. Accounting: company members read/write (sales & export flows post
--    transactions); only finance roles delete
-- ----------------------------------------------------------------------------

do $$
declare
  t text;
  finance constant text := '{admin,manager,accountant}';
begin
  foreach t in array array[
    'accounts', 'bank_accounts', 'bank_reconciliations', 'bank_transactions',
    'transactions', 'transaction_rules'
  ] loop
    perform pg_temp.reset_policies(
      t,
      pg_temp.tenant(), pg_temp.tenant(), pg_temp.tenant(),
      pg_temp.tenant_role(finance),
      true);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 6. Payroll / HR: finance roles manage; employees see their own records
-- ----------------------------------------------------------------------------

do $$
declare
  t text;
  finance constant text := '{admin,manager,accountant}';
  self_row text := format('(%s and employee_id::text = (select core.current_employee_id()))', pg_temp.tenant());
begin
  -- Per-employee records.
  foreach t in array array[
    'payroll_entries', 'payroll_adjustments', 'employee_benefits',
    'vacation_transactions', 'deductions', 'employee_offboardings'
  ] loop
    perform pg_temp.reset_policies(
      t,
      pg_temp.tenant_role(finance) || ' or ' || self_row,
      pg_temp.tenant_role(finance),
      pg_temp.tenant_role(finance),
      pg_temp.tenant_role(finance),
      true);
  end loop;

  -- Employees file their own time-off requests from the Employee Portal.
  perform pg_temp.reset_policies(
    'time_off_requests',
    pg_temp.tenant_role(finance) || ' or ' || self_row,
    pg_temp.tenant_role(finance) || ' or ' || self_row,
    pg_temp.tenant_role(finance),
    pg_temp.tenant_role(finance),
    true);

  perform pg_temp.reset_policies(
    'payroll_runs',
    pg_temp.tenant_role(finance), pg_temp.tenant_role(finance),
    pg_temp.tenant_role(finance), pg_temp.tenant_role(finance),
    true);

  -- Catalogues visible company-wide, managed by finance.
  foreach t in array array['pay_groups', 'benefits'] loop
    perform pg_temp.reset_policies(
      t,
      pg_temp.tenant(), pg_temp.tenant_role(finance),
      pg_temp.tenant_role(finance), pg_temp.tenant_role(finance),
      true);
  end loop;

  -- Employee directory is read company-wide (projects, TD1 form); employees
  -- may update their own row from the Employee Portal.
  perform pg_temp.reset_policies(
    'employees',
    pg_temp.tenant(),
    pg_temp.tenant_role(finance),
    pg_temp.tenant_role(finance) || format(' or (%s and id::text = (select core.current_employee_id()))', pg_temp.tenant()),
    pg_temp.tenant_role(finance),
    true);
end $$;

-- ----------------------------------------------------------------------------
-- 7. Audit logs: append-only; admins & managers read their company's
-- ----------------------------------------------------------------------------

select pg_temp.reset_policies(
  'audit_logs',
  pg_temp.tenant_role('{admin,manager}'),
  '(company_id is null or ' || pg_temp.tenant() || ')',
  null,
  null,
  true);

-- ----------------------------------------------------------------------------
-- 8. Companies: members read their own; admin & manager edit; only
--    super_admin creates or deletes
-- ----------------------------------------------------------------------------

select pg_temp.reset_policies(
  'companies',
  pg_temp.tenant('id'),
  '(select core.is_super_admin())',
  pg_temp.tenant_role('{admin,manager}', 'id'),
  '(select core.is_super_admin())',
  false);

-- ----------------------------------------------------------------------------
-- 9. Shared reference data: readable by any signed-in user, super_admin writes
-- ----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['countries', 'currencies', 'ports', 'subdivisions', 'carriers'] loop
    perform pg_temp.reset_policies(
      t, 'true',
      '(select core.is_super_admin())', '(select core.is_super_admin())', '(select core.is_super_admin())',
      false);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 10. Shipment children (no company_id): scoped through local_shipments
-- ----------------------------------------------------------------------------

do $$
declare
  t text;
  via_shipment constant text :=
    '(exists (select 1 from public.local_shipments s where s.id::text = shipment_id::text and '
    || '((select core.is_super_admin()) or s.company_id::text = (select core.current_company_id()))))';
  managers_only constant text :=
    '((select core.is_super_admin()) or (select core.current_user_role()) = any (''{admin,manager}''::text[]))';
begin
  foreach t in array array['gpstracking_points', 'proof_of_deliveries', 'shipment_documents'] loop
    perform pg_temp.reset_policies(
      t, via_shipment, via_shipment, via_shipment,
      '(' || via_shipment || ' and ' || managers_only || ')',
      false);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 11. Favourite listings: personal to the signed-in user
-- ----------------------------------------------------------------------------

select pg_temp.reset_policies(
  'favorite_vehicle_listings',
  '(created_by = (auth.jwt() ->> ''email''))',
  'true',
  '(created_by = (auth.jwt() ->> ''email''))',
  '(created_by = (auth.jwt() ->> ''email''))',
  false);

-- ----------------------------------------------------------------------------
-- 12. core.users
-- ----------------------------------------------------------------------------

do $$
declare r record;
begin
  for r in select policyname from pg_policies where schemaname = 'core' and tablename = 'users' loop
    execute format('drop policy %I on core.users', r.policyname);
  end loop;
end $$;

alter table core.users enable row level security;

-- Users see themselves and their company; super_admin sees everyone.
create policy users_select on core.users for select to authenticated
  using (
    id = auth.uid()
    or (select core.is_super_admin())
    or company_id::text = (select core.current_company_id())
  );

-- Rows are created by the auth trigger or the invite-user edge function only.

-- Self-edits, or admin/manager editing their company's users. The trigger
-- below enforces which columns and roles may change.
create policy users_update on core.users for update to authenticated
  using (
    id = auth.uid()
    or (select core.is_super_admin())
    or (company_id::text = (select core.current_company_id())
        and (select core.current_user_role()) = any ('{admin,manager}'::text[]))
  )
  with check (
    id = auth.uid()
    or (select core.is_super_admin())
    or company_id is null
    or company_id::text = (select core.current_company_id())
  );

create policy users_delete on core.users for delete to authenticated
  using (
    (select core.is_super_admin())
    or (id <> auth.uid()
        and company_id::text = (select core.current_company_id())
        and core.role_rank(role) <= (select core.max_assignable_rank()))
  );

create or replace function core.guard_user_update()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  max_rank integer;
  my_company text;
begin
  -- Service role / SQL editor (no JWT) and super_admin are unrestricted.
  if auth.uid() is null or core.is_super_admin() then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'User id cannot change' using errcode = '42501';
  end if;

  if old.id = auth.uid() then
    if new.role is distinct from old.role
       or new.company_id is distinct from old.company_id
       or new.accessible_modules is distinct from old.accessible_modules
       or new.employee_entity_id is distinct from old.employee_entity_id
       or new.email is distinct from old.email then
      raise exception 'You cannot change your own role, company, module access or employee link'
        using errcode = '42501';
    end if;
    return new;
  end if;

  max_rank := core.max_assignable_rank();
  my_company := core.current_company_id();

  if max_rank = 0 then
    raise exception 'You are not allowed to edit other users' using errcode = '42501';
  end if;
  if old.company_id::text is distinct from my_company then
    raise exception 'You can only manage users in your own company' using errcode = '42501';
  end if;
  if new.company_id is not null and new.company_id::text is distinct from my_company then
    raise exception 'You cannot move users to another company' using errcode = '42501';
  end if;
  if core.role_rank(old.role) > max_rank or core.role_rank(new.role) > max_rank then
    raise exception 'You cannot assign or manage a role above your own' using errcode = '42501';
  end if;

  return new;
end $$;

drop trigger if exists trg_guard_user_update on core.users;
create trigger trg_guard_user_update
  before update on core.users
  for each row execute function core.guard_user_update();

-- Signup must never trust client-supplied metadata for privileges: anyone can
-- call auth.signUp() with arbitrary `data`. invite-user sets the real role and
-- company afterwards with the service role.
create or replace function core.handle_new_auth_user()
returns trigger language plpgsql security definer set search_path to 'public', 'core' as $function$
begin
  insert into core.users (id, email, full_name, accessible_modules, role, company_id,
                          employee_id, department)
  values (new.id, new.email, new.raw_user_meta_data->>'full_name', '[]'::jsonb, 'user', null,
          new.raw_user_meta_data->>'employee_id', new.raw_user_meta_data->>'department')
  on conflict (id) do nothing;
  return new;
end; $function$;

commit;
